# Connect pairs lying on same row, column, or 45-degree diagonal
for col,arr in pts.items():
    for i,(r1,c1) in enumerate(arr):
      for r2,c2 in arr[i+1:]:
        dr,dc=r2-r1,c2-c1
        if dr==0 or dc==0 or abs(dr)==abs(dc):
          sr=0 if dr==0 else (1 if dr>0 else -1)
          sc=0 if dc==0 else (1 if dc>0 else -1)
          n=max(abs(dr),abs(dc))
